CREATE OR REPLACE FUNCTION public.platform_companies() RETURNS TABLE(id uuid,name text,onboarding_status text,created_at timestamptz,details jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform administrator required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT o.id,o.name,o.onboarding_status,o.created_at,coalesce((SELECT jsonb_build_object('company_name',c.company_name,'telephone',coalesce(c.telephone,''),'address',coalesce(c.address,''),'website',coalesce(c.website,''),'employer_nic_number',coalesce(c.employer_nic_number,''),'tax_id',coalesce(c.tax_id,''),'vat_number',coalesce(c.vat_number,''),'email','') FROM public.company_settings c WHERE c.org_id=o.id LIMIT 1),(SELECT i.defaults FROM public.company_setup_invitations i WHERE i.org_id=o.id ORDER BY i.created_at DESC LIMIT 1),'{}'::jsonb) FROM public.organizations o ORDER BY o.created_at DESC; END $$;
CREATE OR REPLACE FUNCTION public.update_platform_company(_actor uuid,_org uuid,_details jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR NOT EXISTS(SELECT 1 FROM public.platform_administrators WHERE user_id=_actor) THEN RAISE EXCEPTION 'Platform administrator required' USING ERRCODE='42501'; END IF; PERFORM public.validate_company_setup(_details); IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=_org) THEN RAISE EXCEPTION 'Company not found'; END IF; UPDATE public.organizations SET name=trim(_details->>'company_name') WHERE id=_org; UPDATE public.company_settings SET company_name=trim(_details->>'company_name'),telephone=coalesce(_details->>'telephone',''),address=coalesce(_details->>'address',''),website=coalesce(_details->>'website',''),employer_nic_number=coalesce(_details->>'employer_nic_number',''),tax_id=coalesce(_details->>'tax_id',''),vat_number=coalesce(_details->>'vat_number',''),updated_by=_actor WHERE org_id=_org; UPDATE public.company_setup_invitations SET company_name=trim(_details->>'company_name'),defaults=(_details-'email')||jsonb_build_object('email',email) WHERE org_id=_org AND accepted_at IS NULL AND revoked_at IS NULL; INSERT INTO public.audit_logs(org_id,employee_id,action,details) VALUES(_org,NULL,'platform_company_updated',jsonb_build_object('actor',_actor)); END $$;
CREATE FUNCTION public.sync_company_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.organizations SET name=NEW.company_name,logo_url=NEW.logo_url WHERE id=NEW.org_id; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.sync_company_identity() FROM PUBLIC;
CREATE TRIGGER sync_company_identity AFTER INSERT OR UPDATE OF company_name,logo_url ON public.company_settings FOR EACH ROW EXECUTE FUNCTION public.sync_company_identity();